  "app.back": "‹ ਵਾਪਸ",
  "app.advance": "ਐਡਵਾਂਸ",
  "app.advh": "ਬਿੱਲ ਤੋਂ ਪਹਿਲਾਂ ਮਿਲਿਆ ਜਾਂ ਦਿੱਤਾ ਪੈਸਾ।",
  "app.intro": "ਤੁਹਾਡੇ ਬਿੱਲ, ਮਿਲਿਆ ਅਤੇ ਦਿੱਤਾ ਪੈਸਾ, ਖਰੀਦ, ਖਰਚੇ ਅਤੇ ਬਕਾਏ, ਸਭ ਇੱਕ ਥਾਂ। ਇਹ ਫ਼੍ਰੀ ਡਾਕੂਮੈਂਟ ਮੇਕਰਾਂ (ਬਿਲਿੰਗ, ਕੋਟੇਸ਼ਨ, ਰਸੀਦ ਆਦਿ) ਦਾ ਹੀ ਸੇਵ ਡਾਟਾ ਵਰਤਦਾ ਹੈ, ਇਸ ਲਈ ਉੱਥੇ ਬਣਿਆ ਹਰ ਬਿੱਲ ਇੱਥੇ ਦਿਸਦਾ ਹੈ। ਫ਼੍ਰੀ, ਬਿਨਾਂ ਲੌਗਇਨ, ਅਤੇ ਡਾਟਾ ਇਸੇ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ।",
  "app.ab.h": "ਛੋਟੇ ਬਿਜ਼ਨਸ ਲਈ ਐਪ ਕੀ ਕਰਦਾ ਹੈ",
  "app.ab.p": "ਬਹੁਤੇ ਫ਼੍ਰੀ ਬਿੱਲ ਮੇਕਰ ਬਿੱਲ ਬਣਾ ਕੇ ਰੁਕ ਜਾਂਦੇ ਹਨ। Nivesh Sahayak App ਅੱਗੇ ਚੱਲਦਾ ਹੈ: ਹਰ ਪੇਮੈਂਟ ਨੂੰ ਉਹਨਾਂ ਬਿੱਲਾਂ ਨਾਲ ਜੋੜਦਾ ਹੈ ਜੋ ਉਹ ਚੁਕਤਾ ਕਰਦੀ ਹੈ, ਤਾਂ ਜੋ ਤੁਹਾਨੂੰ ਹਮੇਸ਼ਾ ਪਤਾ ਰਹੇ ਕਿ ਕਿਸ ਗਾਹਕ ਵੱਲ ਕਿੰਨਾ ਅਤੇ ਕਦੋਂ ਤੋਂ ਬਾਕੀ ਹੈ, ਅਤੇ ਤੁਸੀਂ ਕਿਸ ਨੂੰ ਦੇਣਾ ਹੈ।",
  "app.ab.1": "ਡੈਸ਼ਬੋਰਡ: ਅੱਜ ਦੀ ਅਤੇ ਇਸ ਮਹੀਨੇ ਦੀ ਵਿਕਰੀ, ਲੈਣਾ ਅਤੇ ਦੇਣਾ, ਹੱਥ ਵਿੱਚ ਕੈਸ਼ ਅਤੇ ਬੈਂਕ ਵਿੱਚ ਪੈਸਾ।",
  "app.ab.2": "ਪੈਸਾ ਆਇਆ ਤੇ ਗਿਆ: ਪੇਮੈਂਟ ਇੱਕ ਵਾਰ ਲਿਖੋ ਅਤੇ ਜਿਹੜੇ ਬਿੱਲ ਉਹ ਚੁਕਤਾ ਕਰਦੀ ਹੈ ਉਹਨਾਂ ਉੱਤੇ ਟਿੱਕ ਕਰੋ। ਥੋੜ੍ਹੀ-ਥੋੜ੍ਹੀ ਪੇਮੈਂਟ ਅਤੇ ਐਡਵਾਂਸ ਆਪੇ ਸਾਂਭੇ ਜਾਂਦੇ ਹਨ, ਅਤੇ ਗਾਹਕ ਦਾ ਕੱਟਿਆ TDS ਵੀ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ।",
  "app.ab.3": "ਬਕਾਇਆ ਅਤੇ ਪੁਰਾਣਾਪਣ: ਕਿਸ ਵੱਲ ਕਿੰਨਾ ਬਾਕੀ, 0–30, 31–60, 61–90 ਅਤੇ 90 ਦਿਨਾਂ ਤੋਂ ਵੱਧ ਵਿੱਚ ਵੰਡਿਆ, ਤਿਆਰ WhatsApp ਰਿਮਾਈਂਡਰ ਨਾਲ।",
  "app.ab.4": "ਪਾਰਟੀ ਸਟੇਟਮੈਂਟ: ਕਿਸੇ ਵੀ ਤਾਰੀਖ਼ਾਂ ਦਾ ਸਟੇਟਮੈਂਟ ਆਫ਼ ਅਕਾਊਂਟ, ਪ੍ਰਿੰਟ ਕਰੋ ਜਾਂ PDF ਭੇਜੋ।",
  "app.ab.5": "ਖਰੀਦ ਅਤੇ ਖਰਚੇ: ਸਪਲਾਇਰ ਦੇ ਬਿੱਲ, CGST, SGST ਜਾਂ IGST ਆਪੇ; ਖਰੀਦ ਵਾਪਸੀ; ਅਤੇ ਰੋਜ਼ ਦੇ ਖਰਚੇ ਜਿਵੇਂ ਕਿਰਾਇਆ, ਬਿਜਲੀ, ਪੈਟਰੋਲ।",
  "app.ab.6": "ਕੈਸ਼ ਬੁੱਕ ਅਤੇ ਬੈਂਕ ਬੁੱਕ: ਹਰ ਕੈਸ਼ ਅਤੇ ਬੈਂਕ ਐਂਟਰੀ, ਚੱਲਦੇ ਬੈਲੰਸ ਨਾਲ।",
  "app.ab.7": "ਇੱਕ ਕਲਿੱਕ ਵਿੱਚ ਬਦਲੋ: ਕੋਟੇਸ਼ਨ ਤੋਂ ਸੇਲਜ਼ ਆਰਡਰ, ਡਿਲੀਵਰੀ ਚਲਾਨ ਜਾਂ ਇਨਵੌਇਸ, ਬਿਨਾਂ ਦੁਬਾਰਾ ਲਿਖੇ।",
  "app.ab.end": "ਅੰਦਰੋਂ ਹਰ ਬਿੱਲ, ਪੇਮੈਂਟ ਅਤੇ ਖਰਚਾ ਸਹੀ ਡਬਲ-ਐਂਟਰੀ ਖਾਤਾ ਬਣਦਾ ਹੈ, ਜਿਵੇਂ ਅਕਾਊਂਟੈਂਟ ਚਾਹੁੰਦੇ ਹਨ।",
  "app.ab.link": "ਪੜ੍ਹੋ ਐਪ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ",
