  "b2.bvon": "{d} ਨੂੰ ਬੁੱਕ ਵੈਲਿਊ: {a}। ਜੋ ਫ਼ਰਕ ਹੈ ਉਹ ਵਿਕਰੀ ਉੱਤੇ ਨਫ਼ਾ ਜਾਂ ਨੁਕਸਾਨ ਹੈ।",
