  "mk.taxnote": "ਟੀਸੀਐੱਸ ਵਿਕਰੀ ਵਿੱਚੋਂ ਵਾਪਸੀ ਘਟਾ ਕੇ, ਜੀਐੱਸਟੀ ਤੋਂ ਬਿਨਾਂ ਮੁੱਲ ਉੱਤੇ ਜਾਂਚਿਆ ਜਾਂਦਾ ਹੈ। ਟੀਡੀਐੱਸ ਕੁੱਲ ਵਿਕਰੀ ਵਿੱਚੋਂ ਵਾਪਸੀ ਘਟਾ ਕੇ ਜਾਂਚਿਆ ਜਾਂਦਾ ਹੈ। ਛੋਟੇ ਸੇਲਰਾਂ ਦੇ ਆਰਡਰ ਟੀਡੀਐੱਸ ਤੋਂ ਮੁਕਤ ਹੋ ਸਕਦੇ ਹਨ ਅਤੇ ਸੇਲਰ ਕੋਲ ਘੱਟ ਦਰ ਦਾ ਸਰਟੀਫ਼ਿਕੇਟ ਹੋ ਸਕਦਾ ਹੈ। ਕਲੇਮ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਟੀਸੀਐੱਸ ਕ੍ਰੈਡਿਟ ਜੀਐੱਸਟੀ ਪੋਰਟਲ ਵਿੱਚ ਅਤੇ ਟੀਡੀਐੱਸ ਫ਼ਾਰਮ 26AS ਜਾਂ ਏਆਈਐੱਸ ਵਿੱਚ ਵੇਖੋ।",
