  "mk.booksp": "ਮੁਫ਼ਤ Nivesh Sahayak ਐਪ ਵਿੱਚ ਮਾਰਕੀਟਪਲੇਸ ਇੱਕ ਗਾਹਕ ਵਾਂਗ ਦਿਸਦਾ ਹੈ: ਮਿਲਿਆ ਪੈਸਾ, ਫ਼ੀਸ (ਖ਼ਰਚ ਵਜੋਂ), ਟੀਸੀਐੱਸ ਅਤੇ ਟੀਡੀਐੱਸ ਮਿਲ ਕੇ ਉਸਦਾ ਬਕਾਇਆ ਚੁਕਾਉਂਦੇ ਹਨ। ਤੁਹਾਡੇ ਬਿੱਲ ਅਤੇ ਕ੍ਰੈਡਿਟ ਨੋਟ ਪਹਿਲਾਂ ਤੋਂ ਬਹੀਆਂ ਵਿੱਚ ਹੋਣੇ ਚਾਹੀਦੇ ਹਨ।",
