  "pk.menu": "ਟਰੇਡ ਪੈਕ",
  "pk.title": "ਟਰੇਡ ਪੈਕ",
  "pk.intro": "ਇੱਕ ਟੈਪ ਨਾਲ ਆਪਣਾ ਕਾਰੋਬਾਰ ਸ਼ੁਰੂ ਕਰੋ: HSN ਜਾਂ SAC ਤੇ GST ਦਰ ਵਾਲੀ ਸਮਾਨ ਦੀ ਤਿਆਰ ਸੂਚੀ, ਬਿੱਲ ਦੀਆਂ ਸੈਟਿੰਗਾਂ, ਕਾਰੋਬਾਰ ਲਈ ਲੋੜੀਂਦੇ ਐਪ ਫ਼ੀਚਰ ਤੇ ਹੋਮ ਸਕ੍ਰੀਨ ਦੇ ਬਾਕਸ। ਪਹਿਲਾਂ ਸਭ ਕੁਝ ਦਿਸਦਾ ਹੈ ਤੇ ਪੈਕ ਮੁੜ ਹਟਾਇਆ ਜਾ ਸਕਦਾ ਹੈ।",
  "pk.limit": "ਪੈਕ ਸਿਰਫ਼ ਜੋੜਦਾ ਹੈ। ਤੁਹਾਡਾ ਸੇਵ ਕੀਤਾ ਕੁਝ ਨਹੀਂ ਹਟਦਾ ਜਾਂ ਬਦਲਦਾ: ਉਸੇ ਨਾਂ ਦਾ ਆਈਟਮ ਛੱਡ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ, ਭਰੀ ਹੋਈ ਸੈਟਿੰਗ ਰਹਿੰਦੀ ਹੈ, ਕੁਝ ਬੰਦ ਨਹੀਂ ਹੁੰਦਾ। ਵਿਕਰੀ ਦਾ ਭਾਅ ਖ਼ਾਲੀ ਰਹਿੰਦਾ ਹੈ, ਤੁਸੀਂ ਆਪ ਭਰੋ। ਆਈਟਮ ਦੇ ਨਾਂ ਤੇ ਨੋਟ ਅੰਗਰੇਜ਼ੀ ਵਿੱਚ ਹਨ।",
  "pk.nobiz": "ਪਹਿਲਾਂ ਆਪਣਾ ਕਾਰੋਬਾਰ ਜੋੜੋ (ਸੈਟਿੰਗਾਂ ਤੇ ਸੇਵ ਕੀਤਾ ਡਾਟਾ), ਫਿਰ ਇੱਥੇ ਆਓ।",
