  "pk.safe": "ਤੁਸੀਂ ਪੈਕ ਬਾਅਦ ਵਿੱਚ ਹਟਾ ਸਕਦੇ ਹੋ: ਸਿਰਫ਼ ਉਹੀ ਹਟੇਗਾ ਜੋ ਪੈਕ ਨੇ ਜੋੜਿਆ ਤੇ ਤੁਸੀਂ ਬਦਲਿਆ ਨਹੀਂ।",
