  "cap.title": "ਸਪਲਾਇਰ ਦਾ ਬਿੱਲ ਸਕੈਨ ਕਰੋ",
  "cap.intro": "ਆਪਣੇ ਸਪਲਾਇਰ ਦੇ ਬਿੱਲ ਦੀ ਫੋਟੋ ਖਿੱਚੋ ਜਾਂ ਚੁਣੋ। ਲਿਖਤ ਇਸੇ ਡਿਵਾਈਸ ਉੱਤੇ ਪੜ੍ਹੀ ਜਾਂਦੀ ਹੈ, ਫੋਟੋ ਕਿਤੇ ਨਹੀਂ ਭੇਜੀ ਜਾਂਦੀ। ਕੁਝ ਵੀ ਸੇਵ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਤੁਸੀਂ ਹਰ ਖਾਨਾ ਜਾਂਚਦੇ ਹੋ।",
