  "cap.confirm": "ਅਜੇ ਕੁਝ ਸੇਵ ਨਹੀਂ ਹੋਇਆ। ਅੱਗੇ ਤੁਹਾਨੂੰ ਆਮ ਖਰੀਦ ਬਿੱਲ ਫਾਰਮ ਦਿਸੇਗਾ ਜਿਸ ਵਿੱਚ ਇਹ ਮੁੱਲ ਭਰੇ ਹੋਣਗੇ; ਪੀਲੇ ਖਾਨੇ ਪੱਕੇ ਨਹੀਂ ਸਨ, ਲਾਲ ਬਿੰਦੀਆਂ ਵਾਲੇ ਨਹੀਂ ਮਿਲੇ। ਹਰ ਇੱਕ ਨੂੰ ਕਾਗਜ਼ ਦੇ ਬਿੱਲ ਨਾਲ ਮਿਲਾਓ, ਫਿਰ ਸੇਵ ਦਬਾਓ।",
