  "pr.pfintro": "ਮਹੀਨੇ ਦੀਆਂ ਸੈਲਰੀ ਸਲਿੱਪਾਂ ਤੋਂ EPFO ਯੂਨੀਫ਼ਾਈਡ ਪੋਰਟਲ ਲਈ ECR ਟੈਕਸਟ ਫ਼ਾਈਲ ਅਤੇ ਚਲਾਨ ਦੀਆਂ ਰਕਮਾਂ ਬਣਦੀਆਂ ਹਨ। ਪਹਿਲਾਂ ਸਲਿੱਪਾਂ ਬਣਾਓ (ਸੈਲਰੀ ਟੈਬ); ਬਿਨਾਂ ਸਲਿੱਪ ਵਾਲੇ ਮੁਲਾਜ਼ਮ ਹੇਠਾਂ ਦਿਸਦੇ ਹਨ।",
  "pr.unver_pf": "ਅੱਪਲੋਡ ਤੋਂ ਪਹਿਲਾਂ ਚੈੱਕ ਕਰੋ: ਇਹ ਬਣਾਉਂਦੇ ਸਮੇਂ (14 Nov 2026) EPFO ਦਾ ਆਪਣਾ ਫ਼ਾਈਲ-ਬਣਤਰ ਵਾਲਾ ਡਾਕੂਮੈਂਟ ਨਹੀਂ ਖੁੱਲ੍ਹ ਸਕਿਆ। 11 ਫ਼ੀਲਡ ਅਤੇ ਉਹਨਾਂ ਦਾ ਕ੍ਰਮ ਪੇਰੋਲ ਸੌਫ਼ਟਵੇਅਰ ਬਣਾਉਣ ਵਾਲਿਆਂ ਦੀ ਜਾਣਕਾਰੀ ਮੁਤਾਬਕ ਹਨ। ਫ਼ਾਈਲ EPFO ਪੋਰਟਲ ਦੇ ECR ਪੇਜ ’ਤੇ ਅੱਪਲੋਡ ਕਰੋ; ਜੇ ਪੋਰਟਲ ਕੋਈ ਲਾਈਨ ਰੱਦ ਕਰੇ ਤਾਂ ਕਾਰਨ ਦੱਸਦਾ ਹੈ।",
