  "it.m_senior": "60 ਸਾਲ ਜਾਂ ਵੱਧ ਉਮਰ ਦਾ ਰੈਜ਼ੀਡੈਂਟ, ਜਿਸ ਦੀ ਕੋਈ ਬਿਜ਼ਨਸ ਜਾਂ ਪ੍ਰੋਫ਼ੈਸ਼ਨ ਦੀ ਆਮਦਨ ਨਹੀਂ, ਐਡਵਾਂਸ ਟੈਕਸ ਨਹੀਂ ਦਿੰਦਾ (section 403(3))। ਬਾਕੀ ਰਕਮ ਰਿਟਰਨ ਭਰਨ ਵੇਲੇ ਦਿਓ।",
