  "it.basis": "ਇਹ ਅੰਕੜੇ ਕਿਸ ਆਧਾਰ ’ਤੇ ਹਨ ({d} ਮੁਤਾਬਕ)",
  "it.b1": "ਰੇਟ ({d} ਮੁਤਾਬਕ), ਟੈਕਸ ਸਾਲ 2026-27: ਨਵੀਂ ਰਿਜੀਮ ₹4 ਲੱਖ ਤੱਕ ਕੁਝ ਨਹੀਂ, ₹8 ਲੱਖ ਤੱਕ 5%, ₹12 ਲੱਖ ਤੱਕ 10%, ₹16 ਲੱਖ ਤੱਕ 15%, ₹20 ਲੱਖ ਤੱਕ 20%, ₹24 ਲੱਖ ਤੱਕ 25%, ਉੱਪਰ 30%; ਰਿਬੇਟ ਤਾਂ ਜੋ ₹12 ਲੱਖ ਤੱਕ ਦੀ ਆਮਦਨ ’ਤੇ ਕੋਈ ਟੈਕਸ ਨਾ ਲੱਗੇ, ਥੋੜ੍ਹਾ ਉੱਪਰ ਮਾਰਜਿਨਲ ਰਿਲੀਫ਼ ਨਾਲ; ਤਨਖ਼ਾਹ ’ਤੇ ਸਟੈਂਡਰਡ ਡਿਡਕਸ਼ਨ ₹75,000। ਪੁਰਾਣੀ ਰਿਜੀਮ: ₹2.5 ਲੱਖ ਤੱਕ ਕੁਝ ਨਹੀਂ (60 ’ਤੇ ₹3 ਲੱਖ, 80 ’ਤੇ ₹5 ਲੱਖ), ₹5 ਲੱਖ ਤੱਕ 5%, ₹10 ਲੱਖ ਤੱਕ 20%, ਉੱਪਰ 30%; ₹5 ਲੱਖ ਤੱਕ ਰਿਬੇਟ ₹12,500; ਸਟੈਂਡਰਡ ਡਿਡਕਸ਼ਨ ₹50,000। ਇਹ ਉਹੀ ਰੇਟ ਹਨ ਜੋ ਸੈਲਰੀ ਸਲਿੱਪ ਟੂਲ ਪਹਿਲਾਂ ਹੀ ਵਰਤਦਾ ਹੈ; ਇਸ ਬਿਲਡ ਵਿੱਚ Finance Act ਤੋਂ ਦੁਬਾਰਾ ਨਹੀਂ ਪੜ੍ਹੇ ਗਏ, ਇਸ ਲਈ ਚੈੱਕ ਕਰੋ।",
  "it.b2": "ਐਡਵਾਂਸ ਟੈਕਸ (Income-tax Act 2025, sections 403 ਤੋਂ 408): ਜਦੋਂ TDS ਤੋਂ ਬਾਅਦ ਟੈਕਸ ₹10,000 ਜਾਂ ਵੱਧ ਹੋਵੇ; 15 ਜੂਨ ਤੱਕ 15%, 15 ਸਤੰਬਰ ਤੱਕ 45%, 15 ਦਸੰਬਰ ਤੱਕ 75%, 15 ਮਾਰਚ ਤੱਕ ਪੂਰਾ; ਪ੍ਰਿਜ਼ੰਪਟਿਵ ਟੈਕਸਪੇਅਰ 15 ਮਾਰਚ ਤੱਕ ਪੂਰਾ ਦਿੰਦਾ ਹੈ; 31 ਮਾਰਚ ਤੱਕ ਦੀ ਪੇਮੈਂਟ ਉਸੇ ਸਾਲ ਦੀ ਗਿਣੀ ਜਾਂਦੀ ਹੈ; 60 ਸਾਲ ਜਾਂ ਵੱਧ ਦਾ ਰੈਜ਼ੀਡੈਂਟ ਜਿਸ ਦੀ ਬਿਜ਼ਨਸ ਆਮਦਨ ਨਹੀਂ, ਛੋਟ ਵਿੱਚ ਹੈ।",
  "it.b3": "ਵਿਆਜ: section 424 (ਪੁਰਾਣਾ 234B) ਕਮੀ ’ਤੇ ਹਰ ਮਹੀਨੇ ਜਾਂ ਮਹੀਨੇ ਦੇ ਹਿੱਸੇ ਦਾ 1%, ਜਦੋਂ ਟੈਕਸ ਦਾ 90% ਤੋਂ ਘੱਟ ਦਿੱਤਾ ਹੋਵੇ; section 425 (ਪੁਰਾਣਾ 234C) ਪਹਿਲੀਆਂ ਤਿੰਨ ਕਿਸ਼ਤਾਂ ਵਿੱਚੋਂ ਹਰ ਇੱਕ ਦੀ ਕਮੀ ’ਤੇ 3% (ਕੋਈ ਨਹੀਂ ਜੇ 15 ਜੂਨ ਤੱਕ 12% ਅਤੇ 15 ਸਤੰਬਰ ਤੱਕ 36% ਦਿੱਤਾ) ਅਤੇ ਮਾਰਚ ਦੀ ਕਮੀ ’ਤੇ 1%।",
  "it.b5": "ਖਾਤਿਆਂ ਵਾਲਾ ਮੁਨਾਫ਼ਾ ਟੈਕਸ ਵਾਲਾ ਮੁਨਾਫ਼ਾ ਨਹੀਂ: Act ਮੁਤਾਬਕ ਡੈਪ੍ਰੀਸੀਏਸ਼ਨ, ਨਾ-ਮੰਨੇ ਖਰਚੇ ਅਤੇ ਪ੍ਰਿਜ਼ੰਪਟਿਵ ਨਿਯਮ ਇਸ ਨੂੰ ਬਦਲਦੇ ਹਨ। ਇਹ ਪਲੈਨ ਅਤੇ ਡਾਟਾ ਸ਼ੀਟ ਆਪਣੇ ਅਕਾਊਂਟੈਂਟ ਨੂੰ ਦਿਓ।",
  "it.b6": "ਇਹ ਨਹੀਂ ਕੱਢੇ ਜਾਂਦੇ: ਸਰਚਾਰਜ, ਖ਼ਾਸ ਰੇਟਾਂ ਵਾਲਾ ਕੈਪੀਟਲ ਗੇਨ, ਵਿਦੇਸ਼ੀ ਟੈਕਸ ਰਿਲੀਫ਼, ਨਾਬਾਲਗ ਦੀ ਆਮਦਨ ’ਤੇ ਟੈਕਸ, ਅਤੇ ਦੇਰ ਨਾਲ ਰਿਟਰਨ ਦਾ ਵਿਆਜ।",
  "it.b7": "ਕੁਝ ਫ਼ਾਈਲ ਨਹੀਂ ਹੁੰਦਾ ਅਤੇ ਤੁਹਾਡੇ ਖਾਤਿਆਂ ਵਿੱਚ ਕੁਝ ਨਹੀਂ ਚੜ੍ਹਦਾ।",
  "it.itr_h": "ਕੁਝ ਸਵਾਲਾਂ ਦੇ ਜਵਾਬ ਦਿਓ ਅਤੇ ਦੇਖੋ ਕਿਹੜਾ ਰਿਟਰਨ ਫ਼ਾਰਮ ਠੀਕ ਹੈ, ਕਿਉਂ, ਅਤੇ ਕਿਹੜੇ ਕਾਗਜ਼ ਤਿਆਰ ਰੱਖਣੇ ਹਨ।",
