  "it.formd_ITR-1": "ਤਨਖ਼ਾਹ ਜਾਂ ਪੈਨਸ਼ਨ, ਦੋ ਤੱਕ ਮਕਾਨ ਅਤੇ ਵਿਆਜ ਵਰਗੇ ਹੋਰ ਸਰੋਤਾਂ ਵਾਲੇ ਰੈਜ਼ੀਡੈਂਟ ਵਿਅਕਤੀ ਲਈ, ਕੁੱਲ ਆਮਦਨ ₹50 ਲੱਖ ਤੱਕ।",
  "it.formd_ITR-2": "ਬਿਨਾਂ ਬਿਜ਼ਨਸ ਜਾਂ ਪ੍ਰੋਫ਼ੈਸ਼ਨ ਆਮਦਨ ਵਾਲੇ ਵਿਅਕਤੀ ਜਾਂ HUF ਲਈ ਜਿਸ ਦਾ ਕੈਪੀਟਲ ਗੇਨ, ₹50 ਲੱਖ ਤੋਂ ਵੱਧ ਆਮਦਨ, ਦੋ ਤੋਂ ਵੱਧ ਮਕਾਨ, ਵਿਦੇਸ਼ੀ ਜਾਇਦਾਦ ਜਾਂ ਆਮਦਨ ਹੈ, ਜਾਂ ਜੋ ITR-1 ਵਿੱਚ ਨਹੀਂ ਆਉਂਦਾ।",
  "it.formd_ITR-3": "ਉਸ ਵਿਅਕਤੀ ਜਾਂ HUF ਲਈ ਜਿਸ ਦੀ ਬਿਜ਼ਨਸ ਜਾਂ ਪ੍ਰੋਫ਼ੈਸ਼ਨ ਆਮਦਨ ਪ੍ਰਿਜ਼ੰਪਟਿਵ ਸਕੀਮ ਹੇਠ ਨਹੀਂ, ਫ਼ਰਮ ਦੇ ਪਾਰਟਨਰ ਲਈ, ਜਾਂ ਜੋ ITR-4 ਵਿੱਚ ਨਹੀਂ ਆਉਂਦਾ।",
  "it.formd_ITR-4": "ਪ੍ਰਿਜ਼ੰਪਟਿਵ ਬਿਜ਼ਨਸ ਆਮਦਨ ਵਾਲੇ ਰੈਜ਼ੀਡੈਂਟ ਵਿਅਕਤੀ ਜਾਂ HUF ਲਈ, ਕੁੱਲ ਆਮਦਨ ₹50 ਲੱਖ ਤੱਕ, ਤਨਖ਼ਾਹ ਜਾਂ ਪੈਨਸ਼ਨ, ਦੋ ਤੱਕ ਮਕਾਨ ਅਤੇ ਹੋਰ ਸਰੋਤ।",
  "it.formd_ITR-5": "ਫ਼ਰਮਾਂ, LLP, ਵਿਅਕਤੀਆਂ ਦੀਆਂ ਐਸੋਸੀਏਸ਼ਨਾਂ ਅਤੇ ਬਾਡੀ ਆਫ਼ ਇੰਡੀਵਿਜੂਅਲਜ਼ ਲਈ।",
  "it.formd_ITR-6": "ਕੰਪਨੀਆਂ ਲਈ, ਉਹਨਾਂ ਤੋਂ ਛੁੱਟ ਜੋ ਧਾਰਮਿਕ ਜਾਂ ਚੈਰੀਟੇਬਲ ਕੰਮ ਲਈ ਛੋਟ ਮੰਗਦੀਆਂ ਹਨ।",
  "it.formd_ITR-7": "ਟਰੱਸਟਾਂ, ਸੰਸਥਾਵਾਂ, ਰਾਜਨੀਤਕ ਪਾਰਟੀਆਂ ਅਤੇ ਅਜਿਹਿਆਂ ਲਈ।",
  "it.w_company": "ਕੰਪਨੀ ITR-6 ਭਰਦੀ ਹੈ।",
  "it.w_firm": "ਫ਼ਰਮ, LLP ਜਾਂ ਐਸੋਸੀਏਸ਼ਨ ITR-5 ਭਰਦੀ ਹੈ।",
  "it.w_other": "ਟਰੱਸਟ, ਸੰਸਥਾਵਾਂ ਅਤੇ ਰਾਜਨੀਤਕ ਪਾਰਟੀਆਂ ITR-7 ਭਰਦੀਆਂ ਹਨ।",
  "it.w_partner": "ਜਿਸ ਫ਼ਰਮ ਵਿੱਚ ਤੁਸੀਂ ਪਾਰਟਨਰ ਹੋ, ਉਸ ਤੋਂ ਮਿਲੀ ਤਨਖ਼ਾਹ ਜਾਂ ਵਿਆਜ ਬਿਜ਼ਨਸ ਆਮਦਨ ਹੈ, ITR-3 ਵਿੱਚ ਦਿਖਾਈ ਜਾਂਦੀ ਹੈ।",
