  "it.w_agri": "₹5,000 ਤੋਂ ਵੱਧ ਖੇਤੀ ਆਮਦਨ ’ਤੇ ITR-1 ਅਤੇ ITR-4 ਨਹੀਂ ਚੱਲਦੇ।",
