  "it.w_esop": "ਮਾਲਕ ਦੇ ਸ਼ੇਅਰਾਂ ’ਤੇ ਟਾਲੇ ਟੈਕਸ ਲਈ ITR-2 ਜਾਂ ITR-3 ਚਾਹੀਦਾ ਹੈ।",
  "it.w_crypto": "ਵਰਚੁਅਲ ਡਿਜੀਟਲ ਐਸੇਟ ਦੀ ਆਮਦਨ ਲਈ ITR-2 ਜਾਂ ITR-3 ਚਾਹੀਦਾ ਹੈ।",
  "it.w_huf": "ITR-1 ਸਿਰਫ਼ ਵਿਅਕਤੀਆਂ ਲਈ ਹੈ; ਬਿਨਾਂ ਬਿਜ਼ਨਸ ਆਮਦਨ ਵਾਲਾ HUF ITR-2 ਭਰਦਾ ਹੈ।",
  "it.w_pres2": "ਤੁਹਾਡੇ ਬਾਕੀ ਜਵਾਬਾਂ ਕਰਕੇ ITR-4 ਨਹੀਂ ਚੱਲਦਾ, ਇਸ ਲਈ ਬਿਜ਼ਨਸ ਆਮਦਨ ITR-3 ਵਿੱਚ ਜਾਂਦੀ ਹੈ।",
  "it.w_pres": "ਸਾਦੀ ਹੋਰ ਆਮਦਨ ਨਾਲ ਪ੍ਰਿਜ਼ੰਪਟਿਵ ਬਿਜ਼ਨਸ ਆਮਦਨ ITR-4 ਵਿੱਚ ਆਉਂਦੀ ਹੈ।",
  "it.w_simple": "ਸਿਰਫ਼ ਤਨਖ਼ਾਹ, ਮਕਾਨ ਅਤੇ ਵਿਆਜ, ਹੱਦਾਂ ਦੇ ਅੰਦਰ, ITR-1 ਵਿੱਚ ਆਉਂਦੇ ਹਨ।",
  "it.n_forms": "ਸ਼ਰਤਾਂ 31 ਮਾਰਚ 2026 ਨੂੰ ਖ਼ਤਮ ਹੋਏ ਸਾਲ ਲਈ ਨੋਟੀਫ਼ਾਈ ਕੀਤੀਆਂ ਰਿਟਰਨਾਂ ਮੁਤਾਬਕ ਹਨ (ਟੈਕਸ ਪੋਰਟਲਾਂ ਮੁਤਾਬਕ, ITR-1 ਅਤੇ ITR-4 ਹੁਣ ਦੋ ਮਕਾਨਾਂ ਤੱਕ ਮੰਨਦੇ ਹਨ)। ਟੈਕਸ ਸਾਲ 2026-27 ਦੀਆਂ ਰਿਟਰਨਾਂ Income-tax Rules, 2026 ਹੇਠ ਹਾਲੇ ਨੋਟੀਫ਼ਾਈ ਹੋਣੀਆਂ ਹਨ: ਭਰਨ ਤੋਂ ਪਹਿਲਾਂ ਫ਼ਾਰਮ ਦੀ ਆਪਣੀ ਲਿਸਟ ਪੜ੍ਹੋ ਕਿ ਕੌਣ ਇਸ ਨੂੰ ਨਹੀਂ ਵਰਤ ਸਕਦਾ।",
  "it.n_ltcg": "ਲਿਸਟਿਡ ਸ਼ੇਅਰਾਂ ਜਾਂ ਇਕੁਇਟੀ ਫ਼ੰਡਾਂ ’ਤੇ ਛੋਟੇ ਲੌਂਗ-ਟਰਮ ਗੇਨ ਕੁਝ ਸਾਲਾਂ ਵਿੱਚ ITR-1 ਅਤੇ ITR-4 ਵਿੱਚ ਮੰਨੇ ਗਏ ਸਨ; 2026-27 ਲਈ ਇਹ ਪੱਕਾ ਨਹੀਂ, ਇਸ ਲਈ ITR-2 ਸੁਰੱਖਿਅਤ ਚੋਣ ਹੈ ਅਤੇ ਫ਼ਾਰਮ ਦੀ ਆਪਣੀ ਲਿਸਟ ਫ਼ੈਸਲਾ ਕਰਦੀ ਹੈ।",
  "it.n_ae": "Section 44AE (ਮਾਲ ਢੋਣ ਵਾਲੀਆਂ ਗੱਡੀਆਂ) ਦੀਆਂ ਆਪਣੀਆਂ ਸ਼ਰਤਾਂ ਹਨ; ਪ੍ਰਿਜ਼ੰਪਟਿਵ ਫ਼ਾਰਮ ਵਰਤਣ ਤੋਂ ਪਹਿਲਾਂ ਚੈੱਕ ਕਰੋ।",
