  "ca.t": "ਮੇਰੇ ਅਕਾਊਂਟੈਂਟ ਲਈ ਫ਼ਾਈਲ",
  "ca.intro": "ਇੱਕ ਬਿਜ਼ਨਸ ਅਤੇ ਸਮੇਂ ਨੂੰ ਇੱਕੋ ਸਿਰਫ਼-ਪੜ੍ਹਨ ਵਾਲੀ ਫ਼ਾਈਲ (.nsca) ਵਿੱਚ ਪੈਕ ਕਰਦਾ ਹੈ। ਇਸ ਨੂੰ WhatsApp ਜਾਂ ਈਮੇਲ ਨਾਲ ਆਪਣੇ ਅਕਾਊਂਟੈਂਟ ਨੂੰ ਭੇਜੋ। ਉਹ ਇਸ ਨੂੰ ca.niveshsahayak.in ’ਤੇ ਖੋਲ੍ਹਦੇ ਹਨ, ਖਾਤੇ ਪੜ੍ਹਦੇ ਹਨ, ਸਵਾਲ ਜੋੜਦੇ ਹਨ ਅਤੇ ਕਮੈਂਟ ਵਾਪਸ ਤੁਹਾਨੂੰ ਭੇਜਦੇ ਹਨ।",
  "ca.notlive": "ਇਹ ਫ਼ਾਈਲ ਦੇਣਾ ਹੈ, ਲਾਈਵ ਸਾਂਝਾ ਲੌਗਇਨ ਨਹੀਂ। ਤੁਹਾਡਾ ਅਕਾਊਂਟੈਂਟ ਖਾਤੇ ਉਵੇਂ ਦੇਖਦਾ ਹੈ ਜਿਵੇਂ ਫ਼ਾਈਲ ਬਣਾਉਣ ਵੇਲੇ ਸਨ। ਲਾਈਵ ਲੌਗਇਨ ਲਈ ਅਜਿਹਾ ਸਰਵਰ ਚਾਹੀਦਾ ਹੈ ਜੋ ਤੁਹਾਡੇ ਖਾਤੇ ਰੱਖੇ, ਅਤੇ Nivesh Sahayak ਕੋਲ ਕੋਈ ਨਹੀਂ: ਤੁਹਾਡੇ ਖਾਤੇ ਤੁਹਾਡੇ ਡਿਵਾਈਸ ’ਤੇ ਰਹਿੰਦੇ ਹਨ। ਨਵੀਆਂ ਐਂਟਰੀਆਂ ਲਈ ਨਵੀਂ ਫ਼ਾਈਲ ਬਣਾਓ।",
