  "ca.items": "ਖਰੀਦ ਅਤੇ ਵਿਕਰੀ ਰੇਟਾਂ ਨਾਲ ਆਈਟਮ ਲਿਸਟ (ਸਟਾਕ ਲਈ ਜ਼ਰੂਰੀ)",
