  "ca.cIntro": "ਤੁਹਾਡਾ ਅਕਾਊਂਟੈਂਟ ਸਵਾਲਾਂ ਅਤੇ ਕਮੈਂਟਾਂ ਦੀ ਇੱਕ ਛੋਟੀ ਫ਼ਾਈਲ (.nsca-comments) ਵਾਪਸ ਭੇਜਦਾ ਹੈ। ਹਰ ਸਵਾਲ ਉਸ ਦੀ ਐਂਟਰੀ ਦੇ ਨਾਲ ਦੇਖਣ ਲਈ ਇਸ ਨੂੰ ਇੱਥੇ ਲੋਡ ਕਰੋ। ਜਵਾਬ ਦਿਓ, ਬੰਦ ਮਾਰਕ ਕਰੋ, ਅਤੇ ਵਾਪਸ ਭੇਜਣ ਲਈ ਫ਼ਾਈਲ ਦੁਬਾਰਾ ਸੇਵ ਕਰੋ।",
