  "cv.h1": "ਅਕਾਊਂਟੈਂਟ ਵਿਊਅਰ: ਕਲਾਇੰਟ ਦੀ ਭੇਜੀ ਖਾਤਿਆਂ ਵਾਲੀ ਫ਼ਾਈਲ ਖੋਲ੍ਹੋ",
  "cv.intro": "ਤੁਹਾਡਾ ਕਲਾਇੰਟ ਕਿਸੇ ਸਮੇਂ ਦੇ ਆਪਣੇ ਖਾਤੇ ਇੱਕ ਫ਼ਾਈਲ ਵਿੱਚ ਪੈਕ ਕਰਕੇ WhatsApp ਜਾਂ ਈਮੇਲ ਨਾਲ ਤੁਹਾਨੂੰ ਭੇਜਦਾ ਹੈ। ਇਸ ਨੂੰ ਇੱਥੇ ਖੋਲ੍ਹ ਕੇ ਪੜ੍ਹੋ: ਬਕਾਏ, ਪਾਰਟੀਆਂ, ਲੈਜਰ, ਡੇ ਬੁੱਕ, GST ਹਿਸਾਬ, ਫ਼ਾਈਨਲ ਅਕਾਊਂਟਸ ਅਤੇ ਹਰ ਡਾਕੂਮੈਂਟ। ਲੱਭੋ ਅਤੇ ਫ਼ਿਲਟਰ ਕਰੋ, ਕਿਸੇ ਵੀ ਐਂਟਰੀ ’ਤੇ ਸਵਾਲ ਪੁੱਛੋ, ਅਤੇ ਆਪਣੇ ਕਮੈਂਟ ਇੱਕ ਛੋਟੀ ਫ਼ਾਈਲ ਵਜੋਂ ਵਾਪਸ ਭੇਜੋ। ਫ਼੍ਰੀ, ਬਿਨਾਂ ਲੌਗਇਨ, ਅਤੇ ਕੁਝ ਅੱਪਲੋਡ ਨਹੀਂ ਹੁੰਦਾ: ਫ਼ਾਈਲ ਤੁਹਾਡੇ ਬ੍ਰਾਊਜ਼ਰ ਅੰਦਰ ਹੀ ਪੜ੍ਹੀ ਜਾਂਦੀ ਹੈ।",
  "cv.drop": ".nsca ਫ਼ਾਈਲ ਇੱਥੇ ਛੱਡੋ",
