  "cv.how.1": "ਤੁਹਾਡਾ ਕਲਾਇੰਟ Nivesh Sahayak ਖੋਲ੍ਹਦਾ ਹੈ, ਮੇਰਾ ਡਾਟਾ › ਆਪਣੇ ਅਕਾਊਂਟੈਂਟ ਨੂੰ ਭੇਜੋ ਵਿੱਚ ਜਾਂਦਾ ਹੈ, ਅਤੇ ਇੱਕ ਬਿਜ਼ਨਸ ਤੇ ਸਮੇਂ ਲਈ “ਮੇਰੇ ਅਕਾਊਂਟੈਂਟ ਲਈ ਫ਼ਾਈਲ ਬਣਾਓ” ਚੁਣਦਾ ਹੈ।",
  "cv.how.2": "ਉਹ ਤੁਹਾਨੂੰ ਫ਼ਾਈਲ (.nsca ਵਾਲੀ) ਅਤੇ ਉਸੇ ਮੈਸੇਜ ਵਿੱਚ ਇੱਕ ਛੋਟਾ ਚੈੱਕ ਕੋਡ ਭੇਜਦਾ ਹੈ।",
  "cv.how.3": "ਤੁਸੀਂ ਫ਼ਾਈਲ ਇਸ ਪੇਜ ’ਤੇ ਖੋਲ੍ਹਦੇ ਹੋ। ਪੇਜ ਦੱਸਦਾ ਹੈ ਕਿ ਫ਼ਾਈਲ ਬਦਲੀ ਤਾਂ ਨਹੀਂ, ਅਤੇ ਮਿਲਾਉਣ ਲਈ ਕਲਾਇੰਟ ਦਾ ਦਿੱਤਾ ਚੈੱਕ ਕੋਡ ਲਿਖਣ ਦਿੰਦਾ ਹੈ।",
  "cv.how.4": "ਖਾਤੇ ਪੜ੍ਹੋ, ਲੱਭੋ, ਅਤੇ ਕਿਸੇ ਵੀ ਡਾਕੂਮੈਂਟ, ਡੇ ਬੁੱਕ ਐਂਟਰੀ ਜਾਂ ਸਕ੍ਰੀਨ ’ਤੇ “ਸਵਾਲ ਜਾਂ ਕਮੈਂਟ ਜੋੜੋ” ਦਬਾਓ। ਜੋ ਵੀ ਤੁਸੀਂ ਲਿਖਦੇ ਹੋ, ਇਸੇ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ।",
  "cv.how.5": "ਕੰਮ ਪੂਰਾ ਹੋਣ ’ਤੇ “ਸਵਾਲ ਅਤੇ ਕਮੈਂਟ” ਖੋਲ੍ਹੋ ਅਤੇ ਛੋਟੀ .nsca-comments ਫ਼ਾਈਲ ਵਾਪਸ ਭੇਜੋ। ਕਲਾਇੰਟ ਇਸ ਨੂੰ ਲੋਡ ਕਰਕੇ ਹਰ ਸਵਾਲ ਉਸ ਦੀ ਐਂਟਰੀ ਨਾਲ ਦੇਖਦਾ ਹੈ। ਉਹ ਜਵਾਬ ਦੇ ਸਕਦਾ ਹੈ, ਅਤੇ ਤੁਸੀਂ ਜਵਾਬ ਇੱਥੇ ਲੋਡ ਕਰ ਸਕਦੇ ਹੋ।",
  "cv.live.h": "ਫ਼ਾਈਲ ਦੇਣਾ, ਲਾਈਵ ਲੌਗਇਨ ਨਹੀਂ",
  "cv.live.p": "ਇਹ ਫ਼ਾਈਲ ਦੇਣਾ ਹੈ। ਤੁਸੀਂ ਕਲਾਇੰਟ ਦੇ ਅਕਾਊਂਟ ਵਿੱਚ ਲੌਗਇਨ ਨਹੀਂ ਕਰਦੇ ਅਤੇ ਬਾਅਦ ਵਿੱਚ ਕੀਤੇ ਬਦਲਾਅ ਨਹੀਂ ਦੇਖਦੇ। ਲਾਈਵ ਸਾਂਝੇ ਲੌਗਇਨ ਲਈ ਖਾਤੇ ਰੱਖਣ ਵਾਲਾ ਸਰਵਰ ਚਾਹੀਦਾ ਹੈ, ਅਤੇ Nivesh Sahayak ਕੋਲ ਕੋਈ ਨਹੀਂ: ਖਾਤੇ ਕਲਾਇੰਟ ਦੇ ਡਿਵਾਈਸ ’ਤੇ ਰਹਿੰਦੇ ਹਨ। ਨਵੇਂ ਸਮੇਂ ਲਈ ਜਾਂ ਸੁਧਾਰਾਂ ਤੋਂ ਬਾਅਦ, ਕਲਾਇੰਟ ਤੋਂ ਨਵੀਂ ਫ਼ਾਈਲ ਮੰਗੋ।",
  "cv.safe.h": "ਫ਼ਾਈਲ ਵਿੱਚ ਕੀ ਹੈ, ਅਤੇ ਕੀ ਨਹੀਂ",
  "cv.safe.p": "ਕਲਾਇੰਟ ਟਿੱਕ ਕਰਦਾ ਹੈ ਕਿ ਕੀ ਜਾਵੇ। ਆਮ ਤੌਰ ’ਤੇ ਫ਼ਾਈਲ ਵਿੱਚ ਇੱਕ ਬਿਜ਼ਨਸ ਦੀਆਂ ਸਮੇਂ ਦੇ ਅਖ਼ੀਰ ਤੱਕ ਦੀਆਂ ਐਂਟਰੀਆਂ, ਪਾਰਟੀਆਂ ਅਤੇ ਆਈਟਮ ਹੁੰਦੀਆਂ ਹਨ। ਕੋਟੇਸ਼ਨ ਅਤੇ ਆਰਡਰ, ਸੈਲਰੀ ਅਤੇ ਸਟਾਫ਼ ਰਿਕਾਰਡ, ਫ਼ੋਨ ਨੰਬਰ ਅਤੇ ਈਮੇਲ ਪਤੇ, ਅਤੇ ਬਿਜ਼ਨਸ ਦੇ ਬੈਂਕ ਖਾਤੇ ਦੇ ਵੇਰਵੇ ਤਦ ਤੱਕ ਬਾਹਰ ਰਹਿੰਦੇ ਹਨ ਜਦ ਤੱਕ ਕਲਾਇੰਟ ਟਿੱਕ ਨਾ ਕਰੇ। ਫ਼ੋਟੋਆਂ, PIN ਅਤੇ ਬੈਕਅੱਪ ਸੈਟਿੰਗਾਂ ਕਦੇ ਸ਼ਾਮਲ ਨਹੀਂ ਹੁੰਦੀਆਂ। ਫ਼ਾਈਲ ਵਿੱਚ ਚੈੱਕਸਮ ਹੁੰਦਾ ਹੈ, ਇਸ ਲਈ ਕੋਈ ਵੀ ਬਦਲਾਅ ਇਸ ਪੇਜ ’ਤੇ ਦਿਸਦਾ ਹੈ। ਜੋ ਫ਼ਾਈਲ ਬਦਲ ਕੇ ਚੈੱਕਸਮ ਦੁਬਾਰਾ ਕੱਢ ਲਵੇ, ਉਸ ਨੂੰ ਚੈੱਕਸਮ ਨਹੀਂ ਰੋਕ ਸਕਦਾ, ਇਸ ਲਈ ਚੈੱਕ ਕੋਡ ਕਲਾਇੰਟ ਦੇ ਵੱਖਰੇ ਭੇਜੇ ਕੋਡ ਨਾਲ ਮਿਲਾਓ।",
  "cv.readonly": "ਇਹ ਫ਼ਾਈਲ ਦਾ ਸਿਰਫ਼-ਪੜ੍ਹਨ ਵਾਲਾ ਵਿਊ ਹੈ: ਇੱਥੇ ਕੁਝ ਬਦਲਿਆ ਜਾਂ ਸੇਵ ਨਹੀਂ ਹੋ ਸਕਦਾ।",
  "cv.notfile": "ਇਹ Nivesh Sahayak ਅਕਾਊਂਟੈਂਟ ਫ਼ਾਈਲ (.nsca) ਨਹੀਂ ਹੈ।",
  "cv.iscomments": "ਇਹ ਕਮੈਂਟ ਫ਼ਾਈਲ ਹੈ। ਪਹਿਲਾਂ ਖਾਤਿਆਂ ਵਾਲੀ ਫ਼ਾਈਲ (.nsca) ਖੋਲ੍ਹੋ, ਫਿਰ “ਸਵਾਲ ਅਤੇ ਕਮੈਂਟ” ਤੋਂ ਕਮੈਂਟ ਲੋਡ ਕਰੋ।",
  "cv.newer": "ਇਹ ਫ਼ਾਈਲ ਨਵੇਂ ਵਰਜ਼ਨ ਨੇ ਬਣਾਈ ਹੈ। ਪੇਜ ਰੀਲੋਡ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
