  "hm.rm.icsp": "ਅਗਲੇ 60 ਦਿਨਾਂ ਦੀ ਕੈਲੰਡਰ ਫ਼ਾਈਲ ਬਣਾਉਂਦਾ ਹੈ: ਬਿੱਲਾਂ ਦੀਆਂ ਡਿਊ ਡੇਟਾਂ ਅਤੇ ਟੈਕਸ ਦੀਆਂ ਤਾਰੀਖ਼ਾਂ। ਆਪਣੇ ਕੈਲੰਡਰ ਵਿੱਚ ਜੋੜਨ ਲਈ ਇਸ ਨੂੰ ਫ਼ੋਨ ’ਤੇ ਖੋਲ੍ਹੋ, ਜੋ ਇੱਕ ਦਿਨ ਪਹਿਲਾਂ ਆਪੇ ਵੱਜਦਾ ਹੈ, ਭਾਵੇਂ ਇਹ ਐਪ ਬੰਦ ਹੋਵੇ।",
