  "hm.rm.icsnone": "ਅਗਲੇ 60 ਦਿਨਾਂ ਵਿੱਚ ਕੈਲੰਡਰ ਵਿੱਚ ਪਾਉਣ ਲਈ ਕੋਈ ਡਿਊ ਡੇਟ ਨਹੀਂ।",
  "hm.rm.icsdone": "{n} ਤਾਰੀਖ਼ਾਂ ਨਾਲ ਕੈਲੰਡਰ ਫ਼ਾਈਲ ਬਣ ਗਈ। ਜੋੜਨ ਲਈ ਇਸ ਨੂੰ ਖੋਲ੍ਹੋ।",
  "hm.rm.recv": "ਲੈਣਾ",
  "hm.rm.pay": "ਦੇਣਾ",
  "hm.rm.lim": "ਬ੍ਰਾਊਜ਼ਰ ਕੀ ਨਹੀਂ ਕਰ ਸਕਦਾ",
  "hm.rm.l1": "ਬੰਦ ਵੈੱਬ ਪੇਜ ਚੱਲ ਨਹੀਂ ਸਕਦਾ, ਅਤੇ ਇਸ ਐਪ ਪਿੱਛੇ ਕੋਈ ਸਰਵਰ ਨਹੀਂ ਜੋ ਤੁਹਾਨੂੰ ਪੁਸ਼ ਮੈਸੇਜ ਭੇਜੇ। ਇਸ ਲਈ ਐਪ ਦਾ ਰਿਮਾਈਂਡਰ ਸਿਰਫ਼ ਐਪ ਖੋਲ੍ਹਣ ’ਤੇ ਦਿਸਦਾ ਹੈ।",
  "hm.rm.l2": "ਸਭ ਕੁਝ ਤੁਹਾਡੇ ਡਿਵਾਈਸ ’ਤੇ ਕੱਢਿਆ ਜਾਂਦਾ ਹੈ, ਇਸ ਲਈ ਬਿਨਾਂ ਇੰਟਰਨੈੱਟ ਚੱਲਦਾ ਹੈ। ਤੁਹਾਡੇ ਬਿਜ਼ਨਸ ਬਾਰੇ ਕੁਝ ਵੀ ਕਿਤੇ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ।",
  "hm.rm.l3": "ਜੋ ਤਾਰੀਖ਼ਾਂ ਖੁੰਝਣੀਆਂ ਨਹੀਂ ਚਾਹੀਦੀਆਂ, ਉਹਨਾਂ ਲਈ ਕੈਲੰਡਰ ਫ਼ਾਈਲ ਵਰਤੋ: ਫ਼ੋਨ ਦਾ ਕੈਲੰਡਰ ਆਪੇ ਵੱਜਦਾ ਹੈ। ਇਹ ਅੱਜ ਦੀ ਤਸਵੀਰ ਹੈ, ਇਸ ਲਈ ਨਵੇਂ ਬਿੱਲ ਐਂਟਰ ਕਰਨ ਤੋਂ ਬਾਅਦ ਨਵੀਂ ਫ਼ਾਈਲ ਬਣਾਓ।",
  "hm.rm.l4": "ਇੰਸਟਾਲ ਕੀਤੇ ਐਪ ਦੇ ਆਈਕਨ ’ਤੇ ਨੰਬਰ ਦੱਸਦਾ ਹੈ ਕਿ ਕਿੰਨੇ ਜ਼ਰੂਰੀ ਕੰਮ ਹਨ, ਜਿੱਥੇ ਤੁਹਾਡਾ ਫ਼ੋਨ ਇਜਾਜ਼ਤ ਦਿੰਦਾ ਹੈ।",
  "hm.tools.p": "Nivesh Sahayak ਦਾ ਹਰ ਟੂਲ ਇੱਕ ਥਾਂ, ਤੁਸੀਂ ਕੀ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ ਉਸ ਮੁਤਾਬਕ ਵੰਡਿਆ। ਸਾਰੇ ਫ਼੍ਰੀ ਹਨ ਅਤੇ ਇੱਕੋ ਸੇਵ ਡਾਟਾ ’ਤੇ ਚੱਲਦੇ ਹਨ।",
