/* Lines changed on 15 Nov 2026 (ESI template, income-tax source) */
NS.addLang("pa", {
  "pr.e_lastday": "ਇਸ ਰੀਜ਼ਨ ਕੋਡ ਲਈ ਕੰਮ ਦਾ ਆਖਰੀ ਦਿਨ ਚਾਹੀਦਾ ਹੈ",
  "pr.unver_esi": "ਇਹ ਸ਼ੀਟ ESIC ਪੋਰਟਲ ਦੇ ਆਪਣੇ Monthly Contribution ਟੈਂਪਲੇਟ ਵਰਗੀ ਹੈ (15 ਨਵੰਬਰ 2026 ਨੂੰ ਜਾਂਚੀ): ਛੇ ਕਾਲਮ ਟੈਕਸਟ ਵਿੱਚ, Excel 97-2003 (.xls) ਫ਼ਾਈਲ। ਜਿਨ੍ਹਾਂ ਮੁਲਾਜ਼ਮਾਂ ਨੂੰ ਇਸ ਮਹੀਨੇ ਤਨਖ਼ਾਹ ਨਹੀਂ ਮਿਲੀ, ਉਹ ਵੀ ਰੀਜ਼ਨ ਕੋਡ ਨਾਲ ਲਿਸਟ ਵਿੱਚ ਆਉਂਦੇ ਹਨ। ਪਹਿਲਾਂ ਇੱਕ ਮਹੀਨਾ ਅਪਲੋਡ ਕਰਕੇ ਪੋਰਟਲ ਦਾ ਨਤੀਜਾ ਵੇਖ ਲਓ।",
  "it.b4": "ਉੱਪਰਲੇ ਸੈਕਸ਼ਨ 15 ਨਵੰਬਰ 2026 ਨੂੰ ਇਨਕਮ ਟੈਕਸ ਵਿਭਾਗ ਦੀ ਵੈੱਬਸਾਈਟ (incometaxindia.gov.in) ਉੱਤੇ ਦਿੱਤੇ ਸਰਕਾਰੀ ਟੈਕਸਟ ਨਾਲ ਸ਼ਬਦ-ਦਰ-ਸ਼ਬਦ ਜਾਂਚੇ ਗਏ। ਛਪਿਆ ਹੋਇਆ ਐਕਟ ਹੀ ਮੰਨਿਆ ਜਾਵੇਗਾ।",
  "it.f_def_h": "ਕੈਪੀਟਲ ਗੇਨ, ਇਨਾਮ/ਲਾਟਰੀ ਦੀ ਜਿੱਤ, ਡਿਵੀਡੈਂਡ ਜਾਂ ਪਹਿਲੇ ਸਾਲ ਦਾ ਬਿਜ਼ਨਸ ਮੁਨਾਫ਼ਾ ਜੋ ਅਜੇ ਕਮਾਇਆ ਨਹੀਂ: ਬਾਕੀ ਕਿਸ਼ਤਾਂ ਵਿੱਚ ਭਰ ਦਿਓ ਤਾਂ ਪਹਿਲੀਆਂ ਕਿਸ਼ਤਾਂ ਵਿੱਚ ਨਹੀਂ ਗਿਣਿਆ ਜਾਂਦਾ (ਸੈਕਸ਼ਨ 425(4))।"
});

