  "cp.disc": "ਇਹ ਪੰਨਾ ਤੁਹਾਡੇ ਡਿਵਾਈਸ ’ਤੇ ਤੁਹਾਡੇ ਰਿਕਾਰਡ ਤੋਂ ਬਣਿਆ ਯਾਦ ਕਰਾਉਣ ਵਾਲਾ ਪੰਨਾ ਹੈ। ਇਹ ਕਾਨੂੰਨੀ ਜਾਂ ਟੈਕਸ ਸਲਾਹ ਨਹੀਂ। ਫ਼ੈਸਲੇ ਤੋਂ ਪਹਿਲਾਂ ਸਪਲਾਇਰ ਦਾ ਉਦਯਮ ਸਰਟੀਫ਼ਿਕੇਟ ਵੇਖੋ ਅਤੇ CA ਤੋਂ ਪੁੱਛੋ।",
  "cp.lim_p": "ਇਸ ਵਿੱਤੀ ਸਾਲ ਅਤੇ ਪਿਛਲੇ ਸਾਲ ਦੀ ਤੁਹਾਡੀ ਆਪਣੀ ਵਿਕਰੀ (ਟੈਕਸ ਤੋਂ ਬਿਨਾਂ), ਉਨ੍ਹਾਂ ਹੱਦਾਂ ਦੇ ਸਾਹਮਣੇ ਜੋ ਕੰਪੋਜ਼ੀਸ਼ਨ ਸਕੀਮ, ਈ-ਇਨਵੌਇਸ ਅਤੇ ਈ-ਵੇ ਬਿੱਲ ਤੈਅ ਕਰਦੀਆਂ ਹਨ। ਸਿਰਫ਼ ਐਪ ਵਿੱਚ ਦਰਜ ਇਸ ਬਿਜ਼ਨਸ ਦੀ ਵਿਕਰੀ ਗਿਣੀ ਗਈ ਹੈ। ਕਾਨੂੰਨ ਇੱਕ PAN ਦੇ ਸਾਰੇ GSTIN ਅਤੇ ਹੋਰ ਕਿਸਮ ਦਾ ਟਰਨਓਵਰ ਵੀ ਜੋੜਦਾ ਹੈ, ਇਸ ਲਈ CA ਨਾਲ ਮਿਲਾਓ।",
  "cp.s_cur": "ਇਸ ਸਾਲ {fy} ਦੀ ਵਿਕਰੀ",
