  "cp.l_comp_serv": "ਕੰਪੋਜ਼ੀਸ਼ਨ ਸਕੀਮ, ਸਰਵਿਸ: {l} ਤੱਕ",
  "cp.l_einv": "ਈ-ਇਨਵੌਇਸ: {l} ਤੋਂ ਉੱਪਰ ਟਰਨਓਵਰ",
