  "cp.rule_comp_goods": "ਪਿਛਲੇ ਵਿੱਤੀ ਸਾਲ ਦਾ ਟਰਨਓਵਰ ₹1.5 ਕਰੋੜ ਤੱਕ ਹੋਵੇ ਤਾਂ ਕੰਪੋਜ਼ੀਸ਼ਨ ਸਕੀਮ ਲਈ ਜਾ ਸਕਦੀ ਹੈ (ਅਧਿਸੂਚਨਾ 14/2019-ਸੈਂਟਰਲ ਟੈਕਸ)। ਇਸ ਤੋਂ ਉੱਪਰ ਨਹੀਂ।",
  "cp.rule_comp_goods_sp": "ਤੁਹਾਡਾ ਰਾਜ ਅੱਠ ਪਹਾੜੀ ਰਾਜਾਂ ਵਿੱਚ ਹੈ, ਜਿੱਥੇ ਹੱਦ ₹1.5 ਕਰੋੜ ਦੀ ਥਾਂ ₹75 ਲੱਖ ਹੈ (ਅਧਿਸੂਚਨਾ 14/2019-ਸੈਂਟਰਲ ਟੈਕਸ)।",
  "cp.rule_comp_serv": "ਪਿਛਲੇ ਸਾਲ ₹50 ਲੱਖ ਤੱਕ ਟਰਨਓਵਰ ਵਾਲੇ ਸਰਵਿਸ ਦੇਣ ਵਾਲੇ ਕੁੱਲ 6% ਟੈਕਸ (3% ਸੈਂਟਰਲ ਅਤੇ 3% ਰਾਜ) ਦੇ ਸਕਦੇ ਹਨ (ਅਧਿਸੂਚਨਾ 2/2019-ਸੈਂਟਰਲ ਟੈਕਸ (ਰੇਟ))। ਉਹ ਬਿੱਲ ਆਫ਼ ਸਪਲਾਈ ਦਿੰਦੇ ਹਨ, ਟੈਕਸ ਨਹੀਂ ਵਸੂਲ ਸਕਦੇ, ਇਨਪੁੱਟ ਕ੍ਰੈਡਿਟ ਨਹੀਂ ਮਿਲਦਾ ਅਤੇ ਦੂਜੇ ਰਾਜ ਨੂੰ ਸਪਲਾਈ ਨਹੀਂ ਕਰ ਸਕਦੇ।",
  "cp.rule_einv": "ਕੁੱਲ ਟਰਨਓਵਰ ₹5 ਕਰੋੜ ਤੋਂ ਉੱਪਰ ਹੋਵੇ ਤਾਂ ਈ-ਇਨਵੌਇਸ ਲਾਜ਼ਮੀ ਹੈ (ਅਧਿਸੂਚਨਾ 13/2020-ਸੈਂਟਰਲ ਟੈਕਸ, 10/2023 ਨਾਲ ਬਦਲੀ, 1 ਅਗਸਤ 2023 ਤੋਂ)। ਠੀਕ ₹5 ਕਰੋੜ ਉੱਪਰ ਨਹੀਂ ਗਿਣਿਆ ਜਾਂਦਾ। ਅਧਿਸੂਚਨਾ ਪੁਰਾਣੇ ਸਾਲ ਵੀ ਵੇਖਦੀ ਹੈ: CA ਤੋਂ ਪੁੱਛੋ।",
