  "cp.ewb_p": "ਮਾਲ ਦੀ ਖੇਪ ਦੀ ਕੀਮਤ {l} ਤੋਂ ਉੱਪਰ ਹੋਵੇ ਤਾਂ ਲਿਜਾਣ ਲਈ ਈ-ਵੇ ਬਿੱਲ ਚਾਹੀਦਾ ਹੈ (CGST ਨਿਯਮ 138(1))। ਇਹ ਹਰ ਖੇਪ ’ਤੇ ਵੇਖਿਆ ਜਾਂਦਾ ਹੈ, ਸਾਲ ’ਤੇ ਨਹੀਂ। ਜਿਨ੍ਹਾਂ ਬਿੱਲਾਂ ਦੀ ਹਰ ਲਾਈਨ ’ਤੇ ਸਰਵਿਸ ਕੋਡ (SAC, 99 ਤੋਂ ਸ਼ੁਰੂ) ਹੈ ਉਹ ਨਹੀਂ ਗਿਣੇ ਜਾਂਦੇ; ਬਿਨਾਂ ਕੋਡ ਵਾਲੇ ਬਿੱਲ ਗਿਣੇ ਜਾਂਦੇ ਹਨ, ਇਨ੍ਹਾਂ ਨੂੰ ਜਾਂਚ ਲਓ।",
  "cp.ewb_n": "ਇਸ ਸਾਲ ਤੁਹਾਡੇ {n} ਬਿੱਲ ਉਸ ਕੀਮਤ ਤੋਂ ਉੱਪਰ ਹਨ (ਸਭ ਤੋਂ ਵੱਡਾ {m})। ਇਨ੍ਹਾਂ ’ਤੇ ਭੇਜੇ ਮਾਲ ਲਈ ਈ-ਵੇ ਬਿੱਲ ਲੱਗ ਸਕਦਾ ਹੈ; ਸਰਵਿਸ ਲਈ ਨਹੀਂ।",
  "cp.ewb_0": "ਇਸ ਸਾਲ ਕੋਈ ਬਿੱਲ ਉਸ ਕੀਮਤ ਤੋਂ ਉੱਪਰ ਨਹੀਂ।",
  "cp.asof": "{d} ਤੱਕ ਦੀ ਜਾਣਕਾਰੀ। ਹੱਦਾਂ ਅਤੇ ਨਿਯਮ ਬਦਲ ਸਕਦੇ ਹਨ: ਤਾਜ਼ਾ ਅਧਿਸੂਚਨਾ ਵੇਖੋ।",
