  "cp.special": "ਤੁਹਾਡੇ ਬਿਜ਼ਨਸ ਦਾ ਰਾਜ ਉਨ੍ਹਾਂ ਪਹਾੜੀ ਰਾਜਾਂ ਵਿੱਚ ਹੈ ਜਿੱਥੇ ਮਾਲ ਲਈ ਕੰਪੋਜ਼ੀਸ਼ਨ ਦੀ ਹੱਦ ਘੱਟ, ₹75 ਲੱਖ, ਹੈ: ਅਰੁਣਾਚਲ ਪ੍ਰਦੇਸ਼, ਮਣੀਪੁਰ, ਮੇਘਾਲਿਆ, ਮਿਜ਼ੋਰਮ, ਨਾਗਾਲੈਂਡ, ਸਿੱਕਿਮ, ਤ੍ਰਿਪੁਰਾ, ਉੱਤਰਾਖੰਡ।",
  "cp.rc_t": "1 ਜਨਵਰੀ 2027 ਤੋਂ: ਹੋਰ ਸਪਲਾਈ ’ਤੇ ਈ-ਇਨਵੌਇਸ",
  "cp.rc_p": "ਅਧਿਸੂਚਨਾ 04/2026-ਸੈਂਟਰਲ ਟੈਕਸ (26 ਅਕਤੂਬਰ 2026) 1 ਜਨਵਰੀ 2027 ਤੋਂ ਈ-ਇਨਵੌਇਸ ਉਨ੍ਹਾਂ ਸਪਲਾਈ ’ਤੇ ਵੀ ਲਿਆਉਂਦੀ ਹੈ ਜਿਨ੍ਹਾਂ ’ਤੇ ਖ਼ਰੀਦਦਾਰ ਰਿਵਰਸ ਚਾਰਜ ਵਿੱਚ ਟੈਕਸ ਦਿੰਦਾ ਹੈ (ਜਿਵੇਂ ਬਿਨਾਂ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਵਾਲੇ ਸਪਲਾਇਰ ਤੋਂ ਖ਼ਰੀਦ) ਅਤੇ ਸਰਵਿਸ ਦੇ ਆਯਾਤ ’ਤੇ, ₹5 ਕਰੋੜ ਤੋਂ ਉੱਪਰ ਵਾਲਿਆਂ ਲਈ। ਅਧਿਸੂਚਨਾ ਦਾ ਪਾਠ 17 ਨਵੰਬਰ 2026 ਨੂੰ ਪੜ੍ਹਿਆ ਗਿਆ; ਭਰੋਸਾ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਅਧਿਸੂਚਨਾ ਜ਼ਰੂਰ ਵੇਖੋ।",
  "cp.lim_disc": "ਇਹ ਤੁਹਾਡੇ ਆਪਣੇ ਰਿਕਾਰਡ ਤੋਂ ਬਣੇ ਯਾਦ ਕਰਾਉਣ ਵਾਲੇ ਅੰਦਾਜ਼ੇ ਹਨ, ਸਲਾਹ ਨਹੀਂ। ਕਾਨੂੰਨ ਦਾ ਟਰਨਓਵਰ ਇੱਥੇ ਦਰਜ ਵਿਕਰੀ ਤੋਂ ਵੱਧ ਚੀਜ਼ਾਂ ਜੋੜਦਾ ਹੈ। CA ਤੋਂ ਪੁੱਛੋ।",
  "cp.si2027": "1 ਜਨਵਰੀ 2027 ਤੋਂ ਬਿਨਾਂ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਵਾਲੇ ਸਪਲਾਇਰ ਤੋਂ ਰਿਵਰਸ ਚਾਰਜ ਦੀ ਖ਼ਰੀਦ ਦੇ ਸੈਲਫ਼ ਇਨਵੌਇਸ ’ਤੇ, ਟਰਨਓਵਰ ₹5 ਕਰੋੜ ਤੋਂ ਉੱਪਰ ਹੋਵੇ ਤਾਂ, ਈ-ਇਨਵੌਇਸ (IRN) ਵੀ ਲੱਗ ਸਕਦਾ ਹੈ (ਅਧਿਸੂਚਨਾ 04/2026-ਸੈਂਟਰਲ ਟੈਕਸ)। ਅਧਿਸੂਚਨਾ ਵੇਖੋ। ਇਹ ਐਪ ਹਾਲੇ ਸੈਲਫ਼ ਇਨਵੌਇਸ ਦੀ ਈ-ਇਨਵੌਇਸ ਫ਼ਾਈਲ ਨਹੀਂ ਬਣਾ ਸਕਦੀ।",
