  /* Compliance pack (msme.js) */
  "cp.scope": "ਇਹ ਨਿਯਮ ਉਨ੍ਹਾਂ ਮਾਈਕਰੋ ਅਤੇ ਛੋਟੇ ਸਪਲਾਇਰਾਂ ਲਈ ਹੈ ਜੋ ਮਾਲ ਦੇਣ ਵੇਲੇ ਉਦਯਮ ’ਤੇ ਰਜਿਸਟਰ ਸਨ। ਜੋ ਸਪਲਾਇਰ ਸਿਰਫ਼ ਖ਼ਰੀਦ-ਵੇਚ (ਟ੍ਰੇਡਿੰਗ) ਕਰਦਾ ਹੈ, ਉਹ ਆਉਂਦਾ ਹੈ ਜਾਂ ਨਹੀਂ, ਇਹ ਆਪਣੇ CA ਤੋਂ ਪੁੱਛੋ।",
  /* Shared folder mode (sharedfolder.js) */
